// src/components/StudentDetails.jsx
import React from 'react';

export default function StudentDetails({ student }) {
  if (!student) return <div className="card">Select a student to view details.</div>;

  return (
    <div className="card">
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}>
        <div>
          <div style={{fontSize:18,fontWeight:700}}>{student.name}</div>
          <div style={{color:'#9aa6bd',fontSize:13}}>Detailed student result</div>
        </div>
        <div style={{fontSize:12,color:'#9aa6bd'}}>ID: {student.id}</div>
      </div>

      <div style={{marginTop:12}}>
        <p><strong>Section:</strong> {student.section}</p>
        <p><strong>Marks:</strong> {student.marks}</p>
        <p><strong>Grade:</strong> {student.grade}</p>
      </div>
    </div>
  );
}
